// Un envío como objeto: cada dato lleva su nombre
const envio = {
  id: "ENV-4471",
  destinatario: "Ferretería Rossi",
  pesoKg: 18.5,
  urgente: false,
  estado: "en depósito",
};

console.log(envio.destinatario);       // con punto
console.log(envio["pesoKg"]);          // con corchetes
console.log(envio.fragil);             // no existe: da undefined, no un error

envio.estado = "en ruta";              // cambiar un valor
envio.chofer = "M. Pereyra";           // agregar una propiedad nueva
delete envio.urgente;                  // sacar una propiedad
console.log(envio);

console.log("chofer" in envio, "urgente" in envio);

const campo = "estado";                // el nombre del campo llega en una variable
console.log(envio[campo]);

// Las claves son siempre texto, aunque escribas un número
const raro = { "código postal": "C1425", 7: "siete" };
console.log(raro["código postal"], raro[7], raro["7"]);

// El orden: primero las claves que parecen enteros, ordenadas; después el resto, como las agregaste
const o = { b: 1, 10: "x", a: 2, 2: "y" };
console.log(Object.keys(o));

const envio = {
  id: "ENV-4471",
  destino: { calle: "Av. Corrientes 1234", localidad: "CABA", cp: "C1043" },
  bultos: [
    { codigo: "B1", pesoKg: 10 },
    { codigo: "B2", pesoKg: 8.5 },
  ],
};

console.log(envio.destino.localidad);
console.log(envio.bultos[1].pesoKg);

let total = 0;
for (const bulto of envio.bultos) {
  total = total + bulto.pesoKg;
}
console.log("peso total:", total);

const sinDestino = { id: "ENV-4472" };
console.log(sinDestino.destino?.localidad);          // ?. corta y devuelve undefined
console.log(sinDestino.destino?.localidad ?? "sin datos");  // ?? pone un valor por defecto

try {
  console.log(sinDestino.destino.localidad);         // sin ?. explota
} catch (e) {
  console.log("falló con:", e.name);
}

const a = { id: "ENV-1", estado: "en depósito", destino: { cp: "C1043" } };

const b = a;                       // no copia: b y a son dos nombres del mismo objeto
b.estado = "en ruta";
console.log("a.estado:", a.estado);

const c = { ...a };                // copia superficial: un objeto nuevo con las mismas propiedades
c.estado = "entregado";
console.log("a.estado:", a.estado, "| c.estado:", c.estado);

c.destino.cp = "B1900";            // pero destino sigue siendo el mismo objeto de adentro
console.log("a.destino.cp:", a.destino.cp);

const d = structuredClone(a);      // copia profunda: también duplica lo de adentro
d.destino.cp = "X0000";
console.log("a.destino.cp:", a.destino.cp, "| d.destino.cp:", d.destino.cp);

console.log({} === {}, a === b, a === c);

const envios = [
  { id: "ENV-1", estado: "en depósito", pesoKg: 12 },
  { id: "ENV-2", estado: "en ruta",     pesoKg: 30 },
  { id: "ENV-3", estado: "en ruta",     pesoKg: 7.5 },
  { id: "ENV-4", estado: "entregado",   pesoKg: 18 },
  { id: "ENV-5", estado: "en ruta",     pesoKg: 22 },
];

// Un diccionario como contador: la clave es el estado, el valor es cuántos hay
const porEstado = {};
for (const e of envios) {
  porEstado[e.estado] = (porEstado[e.estado] ?? 0) + 1;
}
console.log(porEstado);

console.log(Object.keys(porEstado));     // las claves
console.log(Object.values(porEstado));   // los valores
for (const [estado, cantidad] of Object.entries(porEstado)) {
  console.log(estado + ": " + cantidad);   // cada par [clave, valor]
}

// Lo mismo, sumando kilos por estado
const kilos = {};
for (const e of envios) {
  kilos[e.estado] = (kilos[e.estado] ?? 0) + e.pesoKg;
}
console.log(kilos);

// JSON: ida y vuelta, y lo que se pierde en el camino
const envio = {
  id: "ENV-4471",
  pesoKg: 18.5,
  urgente: false,
  fragil: undefined,                       // undefined
  entrega: new Date("2026-11-13T15:30:00Z"), // una fecha
  etiquetar: () => "imprimir",             // una función
  ratio: NaN,                              // un número que no es número
  bultos: [1, undefined, 3],
};
const texto = JSON.stringify(envio);
console.log(texto);

const vuelta = JSON.parse(texto);
console.log(typeof vuelta.entrega, vuelta.entrega);
console.log(vuelta.entrega instanceof Date);

// Con sangría para leerlo
console.log(JSON.stringify({ id: "ENV-1", destino: { cp: "C1043" } }, null, 2));

// Map y Set no sobreviven
console.log(JSON.stringify({ m: new Map([ ["a", 1] ]), s: new Set([1, 2]) }));

// Un ciclo no se puede escribir
const x = { nombre: "x" };
x.yo = x;
try { JSON.stringify(x); } catch (e) { console.log(e.name); }

// Un BigInt tampoco
try { JSON.stringify({ n: 10n }); } catch (e) { console.log(e.name); }

// Números enormes pierden precisión al leer
console.log(JSON.parse('{"id": 12345678901234567890}').id);

// JSON.parse es estricto: esto es JavaScript válido pero no JSON
const malos = ["{id: 1}", "{'id': 1}", '{"id": 1,}', '{"id": undefined}', ""];
for (const m of malos) {
  try { JSON.parse(m); console.log("válido:", m); }
  catch (e) { console.log(e.name, "con", JSON.stringify(m)); }
}

// Contar palabras de un texto con un objeto común... y con un Map
const texto = "constructor de viajes y constructor de rutas";
const palabras = texto.split(" ");

const conObjeto = {};
for (const p of palabras) {
  conObjeto[p] = (conObjeto[p] ?? 0) + 1;
}
console.log("objeto:", conObjeto);
console.log("'toString' in {}:", "toString" in {});

const conMap = new Map();
for (const p of palabras) {
  conMap.set(p, (conMap.get(p) ?? 0) + 1);
}
console.log("Map:", [...conMap]);
console.log(conMap.size, conMap.get("constructor"));

// Un Map acepta cualquier cosa como clave, y recuerda el orden en que entraron
const m = new Map();
m.set(10, "diez numérico").set("10", "diez de texto");
console.log(m.get(10), "|", m.get("10"), "|", m.size);
const o = {};
o[10] = "diez numérico"; o["10"] = "diez de texto";
console.log(Object.keys(o).length, o[10]);

// Dos salvavidas para el objeto
const limpio = Object.create(null);     // un objeto sin herencia
limpio["constructor"] = (limpio["constructor"] ?? 0) + 1;
console.log(limpio);
console.log(Object.hasOwn({ a: 1 }, "a"), Object.hasOwn({ a: 1 }, "toString"));

// De Map a objeto y de objeto a Map
console.log(JSON.stringify(Object.fromEntries(conMap)));
console.log(new Map(Object.entries({ a: 1, b: 2 })).size);
